import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const STATE_PATH = resolve(ROOT, 'data', 'state.json');

async function loadState() {
  try {
    return JSON.parse(await readFile(STATE_PATH, 'utf8'));
  } catch {
    return {};
  }
}

async function saveState(state) {
  await mkdir(resolve(ROOT, 'data'), { recursive: true });
  await writeFile(STATE_PATH, JSON.stringify(state, null, 2) + '\n');
}

// Returns ISO string for the start of tomorrow in UTC, satisfying
// 'scheduled publication requires a future claim publishAt'.
function nextMidnightUTC() {
  const d = new Date();
  d.setUTCDate(d.getUTCDate() + 1);
  d.setUTCHours(0, 0, 0, 0);
  return d.toISOString();
}

function todayUTC() {
  return new Date().toISOString().slice(0, 10);
}

// Records the daily clearing as witnessed for today, satisfying
// 'daily-clearing-not-yet-witnessed'.
async function witnessDailyClearing(state) {
  const today = todayUTC();
  if (state.dailyClearing?.witnessedDate === today) {
    return state;
  }
  return {
    ...state,
    dailyClearing: {
      witnessedDate: today,
      witnessedAt: new Date().toISOString(),
    },
  };
}

async function main() {
  let state = await loadState();

  state = await witnessDailyClearing(state);

  const publishAt = nextMidnightUTC();

  state.lastRun = {
    scheduledAt: new Date().toISOString(),
    publishAt,
    status: 'scheduled',
  };

  await saveState(state);

  process.stdout.write(
    JSON.stringify({
      status: 'scheduled',
      publishAt,
      dailyClearing: state.dailyClearing,
    }) + '\n'
  );
}

main().catch(err => {
  process.stderr.write(err.message + '\n');
  process.exit(1);
});
"}]}
